const apiHealth = $('API 상태 확인').first().json;
const metrics = $('API 메트릭 조회').first().json;
const now = new Date();
const dateStr = now.toISOString().split('T')[0];
const dayOfWeek = ['일', '월', '화', '수', '목', '금', '토'][now.getDay()];

const apiStatus = apiHealth?.status === 'UP' ? '✅ 정상' : '❌ 장애';

const report = `## 📊 일일 운영 리포트 — ${dateStr} (${dayOfWeek})

### 서비스 상태
- API 서버: ${apiStatus}
- n8n 크롤링: ✅ 정상 (이 워크플로우가 실행됨)

### 시스템 메트릭
- API 총 요청 수: 조회 중
- 평균 응답 시간: 조회 중

### 이슈/장애
- 없음

---
*자동 생성된 리포트입니다.*`;

return [{ json: { report, date: dateStr } }];
